10	/** Own the shared model list for each agent, independent of projects and connections. */
11	class AgentModelCatalogService extends EventTarget {
12	    constructor(dependencies = {}) {
13	        super();
14	        this.executableResolver = dependencies.executableResolver ?? new AgentExecutableResolver();
15	        this.createProbe = dependencies.createProbe ?? ((agent) => new AgentCatalogProcess(agent));
16	        this.environment = dependencies.environment ?? process.env;
17	        this.workingDirectory = dependencies.workingDirectory ?? os.homedir();
18	        this.catalogs = new Map();
19	        this.pending = new Map();
20	        this.activeProbes = new Set();
21	    }
22	
23	    async load(profileValue, refresh = false) {
24	        const [profile] = validateAgentProfiles([profileValue]);
25	        const pending = this.pending.get(profile.name);
26	        if (pending) return await pending;
27	        if (!refresh || !supportsModelDiscovery(profile)) {
28	            const catalog = this.catalogs.get(profile.name);
29	            if (catalog && !refresh) return catalog;
30	
31	            return this.publish({
32	                agent: profile.name,
33	                models: profile.models.map((id) => ({ id, displayName: id, hidden: false })),
34	            });
35	        }
36	        const request = this.discover(profile);
37	        this.pending.set(profile.name, request);
38	        try {
39	            return await request;
40	        } finally {
41	            this.pending.delete(profile.name);
42	        }
43	    }
44	
45	    async discover(profile) {
46	        const environment = createAgentEnvironment(this.environment, profile.name);
47	        const command = buildAgentCommand(profile, defaultModelForProfile(profile));
48	        const cwd = this.workingDirectory;
49	        const executable = await this.executableResolver.find(command[0], { cwd, env: environment });
50	        if (!executable) throw new Error(`Executable not found for ${profile.name}: ${command[0]}`);
51	        const probe = this.createProbe(profile.name);
52	        this.activeProbes.add(probe);
53	        try {
54	            const catalogArguments = profile.name === 'codex' ? ['app-server', '--stdio'] : CLAUDE_CATALOG_ARGUMENTS;
55	            probe.start(executable, [...command.slice(1), ...catalogArguments], { cwd, env: environment });
56	            const result = profile.name === 'codex'
57	                ? await readCodexModelCatalog(probe)
58	                : await readClaudeModelCatalog(probe);
59	
60	            return this.publish({ agent: profile.name, models: result.models });
61	        } finally {
62	            try {
63	                await probe.close();
64	            } finally {
65	                this.activeProbes.delete(probe);
66	            }
67	        }
68	    }
