63	export class AgentCapabilitiesService extends EventTarget {
64	    private availabilityPromise: Promise<void> | null = null;
65	    private availabilityRequest: object | null = null;
66	    private readonly catalogs = new Map<string, AgentCatalogSnapshot>();
67	    private readonly pendingCatalogs = new Map<string, Promise<void>>();
68	    private readonly provider: AgentCapabilitiesProvider;
69	    private snapshot = EMPTY_SNAPSHOT;
70	    private unsubscribeCatalogs: (() => void) | null = null;
71	
72	    constructor(provider: AgentCapabilitiesProvider = hostProvider) {
73	        super();
74	        this.provider = provider;
75	        this.applyCatalog = this.applyCatalog.bind(this);
76	        register('agentCapabilitiesService', this);
77	    }
78	
79	    getSnapshot() {
80	        return this.snapshot;
81	    }
82	
83	    getCatalogSnapshot(agent: string) {
84	        return this.catalogs.get(agent) ?? EMPTY_CATALOG;
85	    }
86	
87	    initialize() {
88	        if (!this.availabilityPromise) {
89	            this.subscribeToCatalogs();
90	            this.availabilityPromise = this.loadAvailability();
91	        }
92	
93	        return this.availabilityPromise;
94	    }
95	
96	    /** Discover available built-in agents once during application startup. */
97	    async refreshStartupCatalogs(profiles: AgentProfile[]) {
98	        await this.initialize();
99	        for (const profile of profiles) {
100	            if (!supportsModelDiscovery(profile) || !this.snapshot.availability.values[profile.name]?.available) continue;
101	            await this.loadCatalog(profile, true);
102	        }
103	    }
104	
105	    /** Reconnect availability and model notifications without discarding the shared lists. */
106	    reload() {
107	        this.subscribeToCatalogs();
108	        this.availabilityPromise = this.loadAvailability();
109	
110	        return this.availabilityPromise;
111	    }
112	
113	    loadCatalog(profile: AgentProfile, refresh = false) {
114	        const pending = this.pendingCatalogs.get(profile.name);
115	        if (pending) return pending;
116	        const previous = this.getCatalogSnapshot(profile.name);
117	        this.catalogs.set(profile.name, { ...previous, error: null, loading: true });
118	        const request = this.readCatalog(profile, refresh);
119	        this.pendingCatalogs.set(profile.name, request);
120	        this.dispatchEvent(new Event(`catalog:${profile.name}`));
121	
122	        return request;
123	    }
124	
125	    private subscribeToCatalogs() {
126	        this.unsubscribeCatalogs?.();
127	        this.unsubscribeCatalogs = this.provider.onModelCatalogChanged?.(this.applyCatalog) ?? null;
128	    }
129	
130	    private applyCatalog(catalog: AgentModelCatalog) {
131	        this.catalogs.set(catalog.agent, { catalog, error: null, loading: this.pendingCatalogs.has(catalog.agent) });
132	        this.dispatchEvent(new Event(`catalog:${catalog.agent}`));
133	    }
134	
135	    private async readCatalog(profile: AgentProfile, refresh: boolean) {
136	        await Promise.resolve();
137	        try {
138	            const catalog = validateAgentModelCatalog(await this.provider.getModelCatalog(profile, refresh));
139	            if (catalog.agent !== profile.name) throw new Error('Model catalog belongs to a different agent');
140	            this.catalogs.set(profile.name, { catalog, error: null, loading: false });
141	        } catch (error) {
142	            this.catalogs.set(profile.name, {
143	                catalog: this.getCatalogSnapshot(profile.name).catalog,
144	                error: errorMessage(error),
145	                loading: false,
146	            });
147	        } finally {
148	            this.pendingCatalogs.delete(profile.name);
149	        }
150	        this.dispatchEvent(new Event(`catalog:${profile.name}`));
151	    }
152	
153	    private async loadAvailability() {
154	        const request = {};
155	        const connection = this.provider.getConnectionIdentity();
156	        this.availabilityRequest = request;
157	        this.snapshot = { availability: { error: null, loading: true, values: {} } };
158	        this.dispatchEvent(new Event('changed'));
159	        try {
160	            const values = await this.provider.getAgentAvailability();
161	            if (request !== this.availabilityRequest || connection !== this.provider.getConnectionIdentity()) return;
162	            this.snapshot = { availability: { error: null, loading: false, values } };
163	        } catch (error) {
164	            if (request !== this.availabilityRequest || connection !== this.provider.getConnectionIdentity()) return;
165	            this.snapshot = { availability: { error: errorMessage(error), loading: false, values: {} } };
166	        }
167	        this.dispatchEvent(new Event('changed'));
168	    }
169	}
