import { createRequire } from 'node:module';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { CodexRuntimeService } = require('./codex_runtime_service');

function bucket(limitId, usedPercent, overrides = {}) {
    return {
        credits: null,
        individualLimit: null,
        limitId,
        limitName: limitId === 'codex' ? 'Codex' : null,
        planType: 'plus',
        primary: { resetsAt: 100, usedPercent, windowDurationMins: 300 },
        rateLimitReachedType: null,
        secondary: null,
        ...overrides,
    };
}

describe('CodexRuntimeService', () => {
    it('publishes each confirmed update mismatch once per session and replays latest state', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribeUpdateRequired(listener);

        expect(service.publishUpdateRequired('0.144.6', '0.146.0')).toBe(true);
        expect(service.publishUpdateRequired('0.144.6', '0.146.0')).toBe(false);
        expect(listener).toHaveBeenCalledOnce();
        expect(listener).toHaveBeenCalledWith({ cacheVersion: '0.146.0', runningVersion: '0.144.6' });

        const lateListener = vi.fn();
        service.subscribeUpdateRequired(lateListener);
        expect(lateListener).toHaveBeenCalledWith({ cacheVersion: '0.146.0', runningVersion: '0.144.6' });
    });

    it('normalizes multi-bucket snapshots and publishes current state to subscribers', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishRateLimits({
            rateLimitResetCredits: { availableCount: 0, credits: [] },
            rateLimits: bucket('codex', 10),
            rateLimitsByLimitId: {
                codex: bucket(null, 20),
                review: bucket('review', 40, {
                    primary: null,
                    secondary: { resetsAt: null, usedPercent: 40, windowDurationMins: null },
                }),
            },
        }, 200)).toBe(true);

        expect(service.getSnapshot()).toEqual({
            available: true,
            buckets: [
                expect.objectContaining({ limitId: 'codex', primary: expect.objectContaining({ usedPercent: 20 }) }),
                expect.objectContaining({ limitId: 'review', secondary: expect.objectContaining({ usedPercent: 40 }) }),
            ],
            observedAt: 200,
            rateLimitResetCredits: { availableCount: 0, credits: [] },
        });
        const lateListener = vi.fn();
        service.subscribe(lateListener);
        expect(listener).toHaveBeenCalledOnce();
        expect(lateListener).toHaveBeenCalledWith(service.getSnapshot());
    });

    it('excludes Spark from mixed full snapshots', () => {
        const service = new CodexRuntimeService();
    it('clears stale supported buckets when a full snapshot contains only Spark', () => {
        const service = new CodexRuntimeService();
        service.publishRateLimits({ rateLimits: bucket('codex', 20) }, 100);

        expect(service.publishRateLimits({rateLimits: bucket('spark', 60, { limitName: 'GPT-5.3-Codex-Spark' })}, 200)).toBe(true);

        expect(service.getSnapshot()).toEqual({
            available: true,
            buckets: [],
            observedAt: 200,
            rateLimitResetCredits: null,
        });
    });

    it('ignores sparse Spark updates without changing supported buckets', () => {
        const service = new CodexRuntimeService();
    it('publishes unavailable state without fabricating usage and keeps no persistence dependency', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishUnavailable(300)).toBe(true);
        expect(service.getSnapshot()).toEqual({
            available: false,
            buckets: [],
            observedAt: 300,
            rateLimitResetCredits: null,
        });
        expect(listener).toHaveBeenCalledWith(service.getSnapshot());
        expect(Object.hasOwn(service, 'persistConversation')).toBe(false);
    });
});
import { createRequire } from 'node:module';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { ClaudeRuntimeService } = require('./claude_runtime_service');

function payload(fiveHourPercent = 20, weeklyPercent = 40) {
    return {
        windows: [
            { id: 'five_hour', resetsAt: 1_000, usedPercent: fiveHourPercent },
            { id: 'weekly', resetsAt: 2_000, usedPercent: weeklyPercent },
        ],
    };
}

describe('ClaudeRuntimeService', () => {
    it('normalizes snapshots and replays current state', () => {
        const service = new ClaudeRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishRateLimits(payload(), 100)).toBe(true);
        expect(service.getSnapshot()).toEqual({ available: true, observedAt: 100, windows: payload().windows });
        const lateListener = vi.fn();
        service.subscribe(lateListener);

        expect(listener).toHaveBeenCalledOnce();
        expect(lateListener).toHaveBeenCalledWith(service.getSnapshot());
    });

    it('rejects partial, malformed, and older snapshots', () => {
        const service = new ClaudeRuntimeService();
        service.publishRateLimits(payload(70), 200);

        expect(service.publishRateLimits(payload(10), 199)).toBe(false);
        expect(service.publishRateLimits({ windows: [payload().windows[0]] }, 201)).toBe(false);
        expect(service.publishRateLimits({
            windows: [
                { ...payload().windows[0], usedPercent: 10.5 },
                payload().windows[1],
            ],
        }, 201)).toBe(false);
        expect(service.getSnapshot()).toMatchObject({ observedAt: 200, windows: [{ usedPercent: 70 }, { usedPercent: 40 }] });
    });

    it('keeps a window Claude reported without a reset time', () => {
        const service = new ClaudeRuntimeService();
        const windows = [{ ...payload().windows[0], resetsAt: null }, payload().windows[1]];

        expect(service.publishRateLimits({ windows }, 100)).toBe(true);
        expect(service.getSnapshot()).toEqual({ available: true, observedAt: 100, windows });
    });

    it('advances observation time without republishing unchanged usage', () => {
        const service = new ClaudeRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);
        service.publishRateLimits(payload(), 100);

        expect(service.publishRateLimits(payload(), 200)).toBe(true);
        expect(service.getSnapshot()).toMatchObject({ observedAt: 200 });
        expect(listener).toHaveBeenCalledOnce();
    });

    it('publishes unavailable state once and keeps newest observation', () => {
        const service = new ClaudeRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishUnavailable(300)).toBe(true);
        expect(service.publishUnavailable(301)).toBe(true);
        expect(service.publishUnavailable(299)).toBe(false);
        expect(service.getSnapshot()).toEqual({ available: false, observedAt: 301, windows: [] });
        expect(listener).toHaveBeenCalledOnce();
    });
});

